     */
    func applyPull(responseJson: String) throws  -> PullOutcome
    
    func children(collection: String, field: String, parent: String?) throws  -> [String]
    
    /**
     * Forgets the space's data (after leaving or being removed).
     */
    func clear() throws 
    
    func counter(collection: String, doc: String, field: String) throws  -> Double
    
    func cursor() throws  -> UInt64
    
    func deleteDoc(collection: String, doc: String) throws 
    
    func failPush() 
    
    /**
     * A plain field's value as JSON, or nil.
     */
    func get(collection: String, doc: String, field: String) throws  -> String?
    
    /**
     * The document as a JSON object (with `id`), or nil if missing or deleted.
     */
    func getDoc(collection: String, doc: String) throws  -> String?
    
    func increment(collection: String, doc: String, field: String, delta: Double) throws 
    
    /**
     * Every live document as a JSON array, sorted by `order_by` then id.
     */
    func list(collection: String, orderBy: String?) throws  -> String
    
    func members(collection: String, doc: String, field: String) throws  -> [String]
    
    func meta(key: String) throws  -> String?
    
    func nodeId()  -> String
    
    func observeServerTime(serverMs: UInt64) throws 
    
    func pendingCount() throws  -> UInt64
    
    func put(collection: String, doc: String, field: String, valueJson: String) throws 
    
    /**
     * Writes several fields of one document: a JSON object of field → value.
     */
    func putDoc(collection: String, doc: String, fieldsJson: String) throws 
    
    func restoreDoc(collection: String, doc: String) throws 
    
    func setAdd(collection: String, doc: String, field: String, member: String) throws 
    
    func setMembers(collection: String, doc: String, field: String, members: [String]) throws 
    
    func setMeta(key: String, value: String?) throws 
    
    func setParent(collection: String, doc: String, field: String, parent: String?) throws 
    
    func setRemove(collection: String, doc: String, field: String, member: String) throws 
    
    /**
     * The body for `POST /push`, or nil when there's nothing to send.
     */
    func takePush() throws  -> String?
    
